class TaskBinding {static Object animal(int kind,String name){return switch(kind){case 0->new alternate.Animal(name);case 1->new alternate.Dog(name);default->new alternate.Puppy(name);};}static String voice(Object x){alternate.Animal a=(alternate.Animal)x;return a.voice();}static String[]actions(Object x){alternate.Puppy p=(alternate.Puppy)x;return new String[]{p.run(),p.bite(),p.jump()};}}
